class Exercise {
    // 값이 바뀌는 줄을 실행 결과와 비교해요.
    static String run(String text) throws Exception {
        // 파일에 저장한 뒤 메모리의 값을 바꿔요.
        var path=java.nio.file.Path.of("quote.txt");
        java.nio.file.Files.writeString(path,text);
        // 메모리의 새 값과 파일은 독립이에요.
        text="changed";
        return text;
    }
}
